function|CREATE OR REPLACE FUNCTION public.add_late_fee(p_request_id uuid, p_booking_id uuid, p_amount bigint, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b public.bookings;prior public.late_fees;fee_id uuid;today_local date;
begin
 if not public.is_admin() then raise exception 'not_authorized' using errcode='42501';end if;
 p_reason:=trim(p_reason);
 select * into prior from public.late_fees where request_id=p_request_id;
 if found then
  if prior.recorded_by<>auth.uid() or prior.booking_id is distinct from p_booking_id then raise exception 'request_id_conflict';end if;
  if prior.amount_piasters is distinct from p_amount or prior.reason is distinct from p_reason then raise exception 'request_id_payload_mismatch';end if;
  return prior.id;
 end if;
 if not exists(select 1 from public.settings where id=true and live_bookings_enabled and date_precision='day' and business_timezone='Africa/Cairo') then raise exception 'policy_decisions_pending';end if;
 if p_request_id is null or p_amount is null or p_amount<=0 or p_amount>9999999999 or p_reason is null or length(p_reason) not between 1 and 500 then raise exception 'invalid_fee';end if;
 today_local:=(now() at time zone 'Africa/Cairo')::date;
 select * into b from public.bookings where id=p_booking_id for update;
 if not found then raise exception 'booking_not_found';end if;
 select * into prior from public.late_fees where request_id=p_request_id;
 if found then
  if prior.recorded_by<>auth.uid() or prior.booking_id is distinct from p_booking_id then raise exception 'request_id_conflict';end if;
  if prior.amount_piasters is distinct from p_amount or prior.reason is distinct from p_reason then raise exception 'request_id_payload_mismatch';end if;
  return prior.id;
 end if;
 if b.status<>'out' or b.returns_on>=today_local then raise exception 'booking_not_currently_overdue';end if;
 insert into public.late_fees(request_id,booking_id,amount_piasters,reason,recorded_by) values(p_request_id,p_booking_id,p_amount,p_reason,auth.uid()) returning id into fee_id;
 return fee_id;
end $function$

function|CREATE OR REPLACE FUNCTION public.admin_dashboard(p_from date, p_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare zone text;today_local date;from_instant timestamptz;until_instant timestamptz;result jsonb;
begin
 if not public.is_admin() then raise exception 'not_authorized' using errcode='42501';end if;
 if p_from is null or p_to is null or p_to<p_from or p_to-p_from>365 then raise exception 'invalid_reporting_period';end if;
 select business_timezone into zone from public.settings where id=true and date_precision='day';
 if zone is distinct from 'Africa/Cairo' then raise exception 'confirmed_timezone_required';end if;
 today_local:=(now() at time zone zone)::date;
 from_instant:=p_from::timestamp at time zone zone;
 until_instant:=(p_to+1)::timestamp at time zone zone;
 select jsonb_build_object(
  'from',p_from,'to',p_to,'today',today_local,
  'active_dresses',(select count(*) from public.dresses where not archived),
  'archived_dresses',(select count(*) from public.dresses where archived),
  'active_employees',(select count(*) from public.profiles where active and role='employee'),
  'confirmed_bookings',(select count(*) from public.bookings where status='confirmed'),
  'outside_bookings',(select count(*) from public.bookings where status='out'),
  'returned_bookings',(select count(*) from public.bookings where status='returned'),
  'overdue_bookings',(select count(*) from public.bookings where status='out' and returns_on<today_local),
  'created_in_period',(select count(*) from public.bookings where created_at>=from_instant and created_at<until_instant),
  'receipt_count',(select count(*) from public.payments where recorded_at>=from_instant and recorded_at<until_instant),
  'receipt_piasters',(select coalesce(sum(amount_piasters),0)::text from public.payments where recorded_at>=from_instant and recorded_at<until_instant),
  'fee_count',(select count(*) from public.late_fees where created_at>=from_instant and created_at<until_instant),
  'fee_piasters',(select coalesce(sum(amount_piasters),0)::text from public.late_fees where created_at>=from_instant and created_at<until_instant),
  'outstanding_piasters',(select coalesce(sum(greatest(0,b.agreed_price_piasters+coalesce(f.total,0)-coalesce(p.total,0))),0)::text from public.bookings b left join (select booking_id,sum(amount_piasters) total from public.late_fees group by booking_id) f on f.booking_id=b.id left join (select booking_id,sum(amount_piasters) total from public.payments group by booking_id) p on p.booking_id=b.id where b.status<>'cancelled')
 ) into result;
 return result;
end $function$

function|CREATE OR REPLACE FUNCTION public.admin_receipt_report(p_from date, p_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare zone text;result jsonb;
begin
 if not public.is_admin() then raise exception 'not_authorized' using errcode='42501';end if;
 if p_from is null or p_to is null or p_to<p_from or p_to-p_from>365 then raise exception 'invalid_reporting_period';end if;
 select business_timezone into zone from public.settings where id=true and date_precision='day';
 if zone is distinct from 'Africa/Cairo' then raise exception 'confirmed_timezone_required';end if;
 with journal as (
  select p.id receipt_id,p.booking_id,p.recorded_at,p.amount_piasters::text amount_piasters,p.method,
   d.code dress_code,d.name dress_name,c.full_name customer_name,c.phone customer_phone,pr.full_name recorded_by_name
  from public.payments p join public.bookings b on b.id=p.booking_id join public.dresses d on d.id=b.dress_id
  join public.customers c on c.id=b.customer_id left join public.profiles pr on pr.id=p.recorded_by
  where p.recorded_at>=p_from::timestamp at time zone zone and p.recorded_at<(p_to+1)::timestamp at time zone zone
  order by p.recorded_at,p.id limit 5001
 ) select jsonb_build_object('from',p_from,'to',p_to,'generated_at',now(),'count',count(*),
  'amount_piasters',coalesce(sum(amount_piasters::numeric),0)::text,
  'rows',coalesce(jsonb_agg(to_jsonb(journal) order by recorded_at,receipt_id),'[]'::jsonb)) into result from journal;
 if (result->>'count')::int>5000 then raise exception 'report_too_large_narrow_period';end if;
 return result;
end $function$

function|CREATE OR REPLACE FUNCTION public.append_dress_image_position()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform 1 from public.dresses where id=new.dress_id for update;
 if exists(select 1 from public.image_deletion_jobs where path=new.path) then raise exception 'image_path_retired';end if;
 select coalesce(max(sort_order),-1)+1 into new.sort_order from public.dress_images where dress_id=new.dress_id;
 return new;
end $function$

function|CREATE OR REPLACE FUNCTION public.begin_employee_account(p_request_id uuid, p_name text, p_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j public.employee_account_jobs;
begin
 if not public.is_admin() then raise exception 'not_authorized' using errcode='42501';end if;
 p_name:=trim(p_name);p_email:=lower(trim(p_email));
 if p_request_id is null or p_name is null or length(p_name) not between 8 and 120 or p_name not like 'اختبار %' or p_email is null or p_email !~ '^test-[a-z0-9][a-z0-9._-]{0,39}@example[.]invalid$' then raise exception 'synthetic_employee_required';end if;
 perform 1 from public.settings where id=true and synthetic_test_enabled for update;
 if not found then raise exception 'functional_portfolio_required';end if;
 select * into j from public.employee_account_jobs where request_id=p_request_id;
 if found then
  if j.actor_id<>auth.uid() then raise exception 'request_id_conflict';end if;
  if j.full_name<>p_name or j.email<>p_email then raise exception 'request_id_payload_mismatch';end if;
  return to_jsonb(j);
 end if;
 if exists(select 1 from public.employee_account_jobs where email=p_email) then raise exception 'employee_email_has_job';end if;
 insert into public.employee_account_jobs(request_id,actor_id,full_name,email) values(p_request_id,auth.uid(),p_name,p_email) returning * into j;
 return to_jsonb(j);
end $function$

function|CREATE OR REPLACE FUNCTION public.cancel_booking(p_request_id uuid, p_booking_id uuid, p_reason text, p_confirm_nonrefundable boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b public.bookings;prior public.booking_cancellations;deposits bigint;extra bigint;fees bigint;result_id uuid;
begin
 if not public.is_admin() then raise exception 'not_authorized' using errcode='42501';end if;
 p_reason:=trim(p_reason);
 if p_request_id is null or p_reason is null or length(p_reason) not between 1 and 500 or p_confirm_nonrefundable is distinct from true then raise exception 'cancellation_confirmation_required';end if;
 select * into b from public.bookings where id=p_booking_id;
 if not found then raise exception 'booking_not_found';end if;
 perform 1 from public.dresses where id=b.dress_id for update;
 select * into b from public.bookings where id=p_booking_id for update;
 select * into prior from public.booking_cancellations where request_id=p_request_id;
 if found then
  if prior.booking_id<>p_booking_id or prior.recorded_by<>auth.uid() then raise exception 'request_id_conflict';end if;
  if prior.reason<>p_reason then raise exception 'request_id_payload_mismatch';end if;
  return prior.id;
 end if;
 if not exists(select 1 from public.settings where id=true and live_bookings_enabled and date_precision='day' and business_timezone='Africa/Cairo' and same_day_allowed=false) then raise exception 'policy_decisions_pending';end if;
 if b.status<>'confirmed' or exists(select 1 from public.handover_records where booking_id=p_booking_id) or exists(select 1 from public.return_records where booking_id=p_booking_id) then raise exception 'cancellation_before_handover_only';end if;
 select coalesce(sum(amount_piasters) filter(where kind='deposit'),0),coalesce(sum(amount_piasters) filter(where kind<>'deposit'),0) into deposits,extra from public.payments where booking_id=p_booking_id;
 select coalesce(sum(amount_piasters),0) into fees from public.late_fees where booking_id=p_booking_id;
 -- Unexpected historic extra receipts/fees require an admin exception policy,
 -- never a guessed refund, deleted payment or changed historical amount.
 if extra<>0 or fees<>0 then raise exception 'financial_exception_requires_admin_review';end if;
 insert into public.booking_cancellations(request_id,booking_id,reason,retained_deposit_piasters,recorded_by)
 values(p_request_id,p_booking_id,p_reason,deposits,auth.uid()) returning id into result_id;
 update public.bookings set status='cancelled' where id=p_booking_id;
 return result_id;
end $function$

function|CREATE OR REPLACE FUNCTION public.complete_dress_image_delete(p_job_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare job public.image_deletion_jobs;
begin
 if not public.is_admin() then raise exception 'not_authorized' using errcode='42501';end if;
 select * into job from public.image_deletion_jobs where id=p_job_id for update;
 if not found then raise exception 'cleanup_job_not_found';end if;
 if job.status='completed' then return;end if;
 if exists(select 1 from public.dress_images where path=job.path) then raise exception 'image_path_still_referenced';end if;
 if exists(select 1 from storage.objects where bucket_id='dress-images' and name=job.path) then raise exception 'storage_object_still_present';end if;
 update public.image_deletion_jobs set status='completed',completed_at=now() where id=job.id;
end $function$

function|CREATE OR REPLACE FUNCTION public.complete_employee_account(p_job_id uuid, p_actor_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j public.employee_account_jobs;p public.profiles;
begin
 if not exists(select 1 from public.profiles where id=p_actor_id and active and role='admin') then raise exception 'active_admin_required';end if;
 select * into j from public.employee_account_jobs where id=p_job_id for update;
 if not found or j.actor_id<>p_actor_id then raise exception 'account_job_not_owned';end if;
 if not exists(select 1 from public.settings where id=true and synthetic_test_enabled) then raise exception 'functional_portfolio_required';end if;
 select * into p from public.profiles where id=j.user_id;
 if found then
  if j.status<>'completed' or p.role<>'employee' then raise exception 'profile_binding_conflict';end if;
  return p.id;
 end if;
 if j.status='completed' then raise exception 'completed_profile_missing';end if;
 if not exists(select 1 from auth.users where id=j.user_id) then raise exception 'auth_user_missing';end if;
 insert into public.profiles(id,full_name,role,active) values(j.user_id,j.full_name,'employee',true);
 update public.employee_account_jobs set status='completed',completed_at=now() where id=j.id;
 return j.user_id;
end $function$

function|CREATE OR REPLACE FUNCTION public.create_booking(p_request_id uuid, p_dress_id uuid, p_customer_name text, p_phone text, p_start date, p_return date, p_total bigint, p_deposit bigint, p_method text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.settings; booking_id uuid; customer_id uuid; prior public.bookings; local_today date;
begin
 p_method:=nullif(trim(p_method),'');
 if p_method is not null and length(p_method)>40 then raise exception 'invalid_payment_method';end if;
 if not public.is_staff() then raise exception 'not_authorized' using errcode='42501';end if;
 select * into prior from public.bookings where request_id=p_request_id;
 if found then
  if prior.created_by<>auth.uid() then raise exception 'request_id_conflict';end if;
  if prior.dress_id is distinct from p_dress_id or prior.starts_on is distinct from p_start or prior.returns_on is distinct from p_return or prior.agreed_price_piasters is distinct from p_total
     or not exists(select 1 from public.customers where id=prior.customer_id and full_name=trim(p_customer_name) and phone=trim(p_phone))
     or coalesce((select amount_piasters from public.payments pay where pay.request_id=p_request_id and pay.booking_id=prior.id and pay.kind='deposit'),0) is distinct from p_deposit
     or (p_deposit>0 and (select method from public.payments pay where pay.request_id=p_request_id and pay.booking_id=prior.id and pay.kind='deposit') is distinct from p_method)
  then raise exception 'request_id_payload_mismatch';end if;
  return prior.id;
 end if;
 select * into s from public.settings where id=true;
 if not s.live_bookings_enabled or s.date_precision is distinct from 'day' or s.same_day_allowed is null or s.business_timezone is null then raise exception 'policy_decisions_pending';end if;
 if not exists(select 1 from pg_catalog.pg_timezone_names where name=s.business_timezone) then raise exception 'invalid_timezone';end if;
 local_today:=(now() at time zone s.business_timezone)::date;
 if p_start is null or p_return is null or p_start<local_today or p_return<p_start or (p_start=local_today and not s.same_day_allowed) then raise exception 'invalid_dates_or_same_day_policy';end if;
 if p_total is null or p_deposit is null or p_total<=0 or p_total>9999999999 or p_deposit<0 or p_deposit>p_total then raise exception 'invalid_amount';end if;
 if p_customer_name is null or length(trim(p_customer_name)) not between 1 and 120 or p_phone is null or length(trim(p_phone)) not between 5 and 24 then raise exception 'invalid_customer';end if;
 if p_method is not null and length(p_method)>40 then raise exception 'invalid_payment_method';end if;
 -- Row lock also serializes against archiving and concurrent booking mutations.
 perform 1 from public.dresses where id=p_dress_id and not archived for update;
 if not found then raise exception 'dress_not_found';end if;
 if exists(select 1 from public.dress_operations where dress_id=p_dress_id and (status='maintenance' or maintenance_required)) then raise exception 'dress_in_maintenance';end if;
 if exists(select 1 from public.return_records r join public.bookings b on b.id=r.booking_id where b.dress_id=p_dress_id and p_start<r.returned_on+2) then raise exception 'actual_preparation_conflict' using errcode='23P01';end if;
 insert into public.customers(full_name,phone) values(trim(p_customer_name),trim(p_phone)) returning id into customer_id;
 insert into public.bookings(request_id,dress_id,customer_id,starts_on,returns_on,agreed_price_piasters,created_by,assigned_to)
 values(p_request_id,p_dress_id,customer_id,p_start,p_return,p_total,auth.uid(),auth.uid()) returning id into booking_id;
 if p_deposit>0 then insert into public.payments(request_id,booking_id,amount_piasters,method,kind,recorded_by) values(p_request_id,booking_id,p_deposit,p_method,'deposit',auth.uid());end if;
 return booking_id;
end $function$

function|CREATE OR REPLACE FUNCTION public.create_portfolio_scenario(p_request_id uuid, p_kind text, p_assigned_to uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare prior public.portfolio_scenarios; target_actor uuid;today_local date;start_day date;return_day date;d uuid;c uuid;b uuid;cat uuid;s public.settings;
begin
 if not public.is_admin() then raise exception 'not_authorized' using errcode='42501';end if;
 if p_request_id is null or p_kind is null or p_kind not in ('handover','return','overdue') then raise exception 'invalid_scenario';end if;
 target_actor:=coalesce(p_assigned_to,auth.uid());
 -- Serializes scenario setup/retry and gate changes, not ordinary bookings.
 select * into s from public.settings where id=true for update;
 if not s.synthetic_test_enabled or not s.live_bookings_enabled or s.date_precision is distinct from 'day' or s.business_timezone is distinct from 'Africa/Cairo' or s.same_day_allowed is distinct from false then raise exception 'functional_portfolio_required';end if;
 select * into prior from public.portfolio_scenarios where request_id=p_request_id;
 if found then
  if prior.actor_id<>auth.uid() then raise exception 'request_id_conflict';end if;
  if prior.kind<>p_kind or prior.assigned_to<>target_actor then raise exception 'request_id_payload_mismatch';end if;
  return prior.booking_id;
 end if;
 if not exists(select 1 from public.profiles where id=target_actor and active and role in ('admin','employee')) then raise exception 'active_test_staff_required';end if;
 select id into cat from public.categories where active order by id limit 1;
 if cat is null then raise exception 'category_required';end if;
 today_local:=(now() at time zone 'Africa/Cairo')::date;
 start_day:=case p_kind when 'handover' then today_local when 'return' then today_local-1 else today_local-3 end;
 return_day:=case p_kind when 'overdue' then today_local-1 else today_local end;
 d:=gen_random_uuid();
 insert into public.dresses(id,code,name,color,size,category_id,public_availability)
 values(d,'CASE-'||replace(d::text,'-',''),'اختبار سيناريو '||p_kind||' · '||today_local::text,'وردي تجريبي','M',cat,'unavailable');
 insert into public.customers(full_name,phone) values('اختبار سيناريو '||p_kind,'TEST-SCENARIO') returning id into c;
 -- This is a fixture initializer, not a same-day booking route. Its fabricated
 -- history is labelled in the UI and isolated from the ordinary create_booking RPC.
 insert into public.bookings(request_id,dress_id,customer_id,starts_on,returns_on,agreed_price_piasters,status,created_by,assigned_to,created_at)
 values(p_request_id,d,c,start_day,return_day,10000,case p_kind when 'handover' then 'confirmed' else 'out' end,auth.uid(),target_actor,(start_day-1)::timestamp at time zone 'Africa/Cairo') returning id into b;
 insert into public.payments(request_id,booking_id,amount_piasters,method,kind,recorded_by,recorded_at)
 values(gen_random_uuid(),b,case p_kind when 'return' then 10000 else 2500 end,'مصطنع دون تحصيل','deposit',auth.uid(),(start_day-1)::timestamp at time zone 'Africa/Cairo');
 if p_kind<>'handover' then
  insert into public.handover_records(request_id,booking_id,card_received,ready_confirmed,handed_over_on,recorded_by,created_at)
  values(gen_random_uuid(),b,true,true,start_day,auth.uid(),start_day::timestamp at time zone 'Africa/Cairo');
 end if;
 insert into public.dress_operations(dress_id,status) values(d,case p_kind when 'handover' then 'in_atelier' else 'outside' end);
 insert into public.portfolio_scenarios values(p_request_id,b,p_kind,auth.uid(),target_actor,now());
 return b;
end $function$

function|CREATE OR REPLACE FUNCTION public.edit_booking(p_request_id uuid, p_booking_id uuid, p_expected_version integer, p_start date, p_return date, p_total bigint, p_reason text, p_confirm boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b public.bookings;prior public.booking_changes;paid numeric;after_v integer;change_id uuid;dates_changed boolean;
begin
 if not public.is_admin() then raise exception 'not_authorized' using errcode='42501';end if;
 p_reason:=trim(p_reason);
 if p_request_id is null or p_expected_version is null or p_expected_version<1 or p_reason is null or length(p_reason) not between 1 and 500 or p_confirm is distinct from true then raise exception 'booking_edit_confirmation_required';end if;
 if p_start is null or p_return is null or p_return<p_start then raise exception 'invalid_booking_edit_dates';end if;
 if p_total is null or p_total<=0 or p_total>9999999999 then raise exception 'invalid_booking_edit_amount';end if;
 select * into b from public.bookings where id=p_booking_id;
 if not found then raise exception 'booking_not_found';end if;
 -- Same lock order as receipts, handover, return and cancellation.
 perform 1 from public.dresses where id=b.dress_id for update;
 select * into b from public.bookings where id=p_booking_id for update;
 select * into prior from public.booking_changes where request_id=p_request_id;
 if found then
  if prior.booking_id<>p_booking_id or prior.recorded_by<>auth.uid() then raise exception 'request_id_conflict';end if;
  if prior.before_version<>p_expected_version or prior.new_start<>p_start or prior.new_return<>p_return or prior.new_price_piasters<>p_total or prior.reason<>p_reason then raise exception 'request_id_payload_mismatch';end if;
  return jsonb_build_object('version',prior.after_version,'unchanged',false,'change_id',prior.id);
 end if;
 if not exists(select 1 from public.settings where id=true and live_bookings_enabled and date_precision='day' and business_timezone='Africa/Cairo' and same_day_allowed=false) then raise exception 'policy_decisions_pending';end if;
 if b.status<>'confirmed' or exists(select 1 from public.handover_records where booking_id=b.id) or exists(select 1 from public.return_records where booking_id=b.id) then raise exception 'booking_edit_before_handover_only';end if;
 if b.version<>p_expected_version then raise exception 'stale_booking_version' using errcode='40001';end if;
 dates_changed:=p_start<>b.starts_on or p_return<>b.returns_on;
 if not dates_changed and p_total=b.agreed_price_piasters then return jsonb_build_object('version',b.version,'unchanged',true,'change_id',null);end if;
 -- Retaining an existing today's scenario date for price-only edits is not a
 -- new same-day booking. A date change must keep the one-day advance policy.
 if dates_changed and exists(select 1 from public.dress_operations where dress_id=b.dress_id and (status='maintenance' or maintenance_required)) then raise exception 'dress_in_maintenance';end if;
 if dates_changed and p_start<=(now() at time zone 'Africa/Cairo')::date then raise exception 'booking_edit_advance_required';end if;
 if dates_changed and exists(select 1 from public.return_records r join public.bookings previous on previous.id=r.booking_id where previous.dress_id=b.dress_id and p_start<r.returned_on+2) then raise exception 'actual_preparation_conflict' using errcode='23P01';end if;
 select coalesce(sum(amount_piasters),0) into paid from public.payments where booking_id=b.id;
 if p_total<paid then raise exception 'booking_price_below_receipts';end if;
 update public.bookings set starts_on=p_start,returns_on=p_return,agreed_price_piasters=p_total where id=b.id returning version into after_v;
 -- The existing exclusion constraint prevents overlap, including the complete
 -- preparation day. Any failed update rolls back the history as one transaction.
