function|CREATE OR REPLACE FUNCTION public.reorder_dress_images(p_dress_id uuid, p_expected_version integer, p_image_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v int;existing uuid[];
begin
 if not public.is_admin() then raise exception 'not_authorized' using errcode='42501';end if;
 select version into v from public.dresses where id=p_dress_id for update;
 if not found then raise exception 'dress_not_found';end if;
 if p_image_ids is null or coalesce(array_ndims(p_image_ids),1)<>1 then raise exception 'invalid_image_list';end if;
 if array_position(p_image_ids,null) is not null then raise exception 'invalid_image_list';end if;
 select coalesce(array_agg(id order by sort_order,id),'{}'::uuid[]) into existing from public.dress_images where dress_id=p_dress_id;
 if cardinality(p_image_ids)<>cardinality(existing) or cardinality(p_image_ids)<>(select count(distinct i) from unnest(p_image_ids) i) or not (p_image_ids @> existing and existing @> p_image_ids) then raise exception 'image_set_changed_refresh';end if;
 -- Exact result already present: safe retry without new writes/audit/version.
 if p_image_ids=existing then return jsonb_build_object('version',v,'unchanged',true);end if;
 if p_expected_version is distinct from v then raise exception 'stale_dress_version' using errcode='40001';end if;
 update public.dress_images i set sort_order=(o.position-1)::int from unnest(p_image_ids) with ordinality o(id,position) where i.id=o.id and i.dress_id=p_dress_id and i.sort_order<>(o.position-1)::int;
 update public.dresses set version=version where id=p_dress_id returning version into v;
 return jsonb_build_object('version',v,'unchanged',false);
end $function$

function|CREATE OR REPLACE FUNCTION public.set_dress_operation(p_dress_id uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare today_local date;held boolean;next_hold boolean;
begin
 if not public.is_staff() or not (public.is_admin() or exists(select 1 from public.bookings where dress_id=p_dress_id and public.can_access_booking(id))) then raise exception 'not_authorized' using errcode='42501';end if;
 if not exists(select 1 from public.settings where id=true and live_bookings_enabled and date_precision='day' and business_timezone='Africa/Cairo') then raise exception 'policy_decisions_pending';end if;
 if p_status is null or p_status not in ('in_atelier','preparation','maintenance') then raise exception 'invalid_state';end if;
 perform 1 from public.dresses where id=p_dress_id for update;
 if not found then raise exception 'dress_not_found';end if;
 if exists(select 1 from public.bookings where dress_id=p_dress_id and status='out') then raise exception 'return_workflow_required';end if;
 select coalesce((select maintenance_required or status='maintenance' from public.dress_operations where dress_id=p_dress_id),false) into held;
 if held and p_status<>'maintenance' and not public.is_admin() then raise exception 'maintenance_admin_clear_required';end if;
 next_hold:=case when p_status='maintenance' then true when p_status='in_atelier' and public.is_admin() then false else held end;
 today_local:=(now() at time zone 'Africa/Cairo')::date;
 if p_status='in_atelier' and exists(select 1 from public.return_records r join public.bookings b on b.id=r.booking_id where b.dress_id=p_dress_id and r.returned_on+2>today_local) then raise exception 'preparation_day_not_finished';end if;
 insert into public.dress_operations(dress_id,status,maintenance_required) values(p_dress_id,p_status,next_hold) on conflict(dress_id) do update set status=excluded.status,maintenance_required=excluded.maintenance_required where public.dress_operations.status is distinct from excluded.status or public.dress_operations.maintenance_required is distinct from excluded.maintenance_required;
end $function$

function|CREATE OR REPLACE FUNCTION public.update_employee_profile(p_request_id uuid, p_employee_id uuid, p_expected_version integer, p_name text, p_active boolean, p_reason text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.profiles;prior public.employee_profile_changes;after_v integer;
begin
 if not public.is_admin() then raise exception 'not_authorized' using errcode='42501';end if;
 p_name:=trim(p_name);p_reason:=trim(p_reason);
 if p_request_id is null or p_expected_version is null or p_name is null or length(p_name) not between 1 and 120 or p_active is null or p_reason is null or length(p_reason) not between 1 and 500 then raise exception 'invalid_employee_change';end if;
 if not exists(select 1 from public.settings where id=true and synthetic_test_enabled) then raise exception 'functional_portfolio_required';end if;
 select * into p from public.profiles where id=p_employee_id for update;
 if not found then raise exception 'employee_not_found';end if;
 if p.role<>'employee' or p.id=auth.uid() then raise exception 'admin_profile_protected';end if;
 select * into prior from public.employee_profile_changes where request_id=p_request_id;
 if found then
  if prior.actor_id<>auth.uid() or prior.employee_id<>p_employee_id then raise exception 'request_id_conflict';end if;
  if prior.before_version<>p_expected_version or prior.new_name<>p_name or prior.new_active<>p_active or prior.reason<>p_reason then raise exception 'request_id_payload_mismatch';end if;
  return prior.after_version;
 end if;
 if p.version<>p_expected_version then raise exception 'stale_employee_version';end if;
 if p.full_name is distinct from p_name and (p_name not like 'اختبار %' or length(p_name)<8) then raise exception 'synthetic_employee_required';end if;
 if p.full_name=p_name and p.active=p_active then return p.version;end if;
 update public.profiles set full_name=p_name,active=p_active where id=p_employee_id returning version into after_v;
 insert into public.employee_profile_changes(request_id,employee_id,actor_id,reason,old_name,new_name,old_active,new_active,before_version,after_version)
 values(p_request_id,p_employee_id,auth.uid(),p_reason,p.full_name,p_name,p.active,p_active,p.version,after_v);
 return after_v;
end $function$

